contract InvMutTest {
    C c;
    constructor() { c = new C(); }
    function __ESBMC_reverted() internal returns (bool) {}
    function __ESBMC_assume(bool) internal pure {}

    receive() external payable {}

    function run(uint depositAmount) public payable { __ESBMC_assume(address(c).balance >= 1000000000000000000000000);
        uint balBefore = address(c).balance;
        uint ownerBalBefore = address(this).balance;
        uint depositsBefore = c.depositsCount(); if (__ESBMC_reverted()) return;

        bool reverted;
        c.withdrawAll(); bool __rev0 = __ESBMC_reverted(); if (__rev0) { reverted = true; } else { reverted = false; }

        uint balAfter = address(c).balance;
        uint ownerBalAfter = address(this).balance;
        uint depositsAfter = c.depositsCount(); if (__ESBMC_reverted()) return;

        assert(
            reverted == (balBefore == 0) &&
            (reverted || (
                balAfter == 0 &&
                ownerBalAfter == ownerBalBefore + balBefore &&
                depositsAfter == depositsBefore
            ))
        );
    }
}

